SET @prov_c := '%s';
SET @id:= '%s';
SET @cat_id := '%s';
SET @send :=  IF((SELECT active FROM sys_report WHERE cat_id = @cat_id and id = @id )=1,0,2);
SET @b_year:=(SELECT yearprocess FROM pk_byear LIMIT 1);
SET	@start_d:=concat(@b_year-1,'1001');
SET @end_d:=concat(@b_year,'0930');

 CREATE TABLE IF NOT EXISTS s_rdu17(
  id varchar(32) NOT NULL,
  hospcode varchar(5) NOT NULL,
  areacode varchar(8) NOT NULL,
  flag_sent varchar(1) DEFAULT NULL,
  date_com varchar(14) DEFAULT NULL,
  b_year varchar(4) NOT NULL,
	target int(9) DEFAULT 0,
	result int(9) DEFAULT 0,
	PRIMARY KEY (id,hospcode,areacode,b_year),
	KEY (hospcode),
	KEY (areacode),
	KEY (b_year)
) ENGINE=MyISAM DEFAULT CHARSET=utf8;

DELETE FROM s_rdu17 WHERE id=@id AND b_year=(@b_year+543);

DROP TEMPORARY TABLE IF  EXISTS  t_ht_rdu ;
CREATE TEMPORARY TABLE IF NOT EXISTS  t_ht_rdu AS
SELECT 
a.*
,if(SUBSTR(o.DIAGCODE,1,4) IN('Z952'),NULL,1) tcount
,d.DATE_SERV,d.DIDSTD,d.DNAME,d.AMOUNT
,IF(ISNULL(a.bdate) AND d.DATE_SERV >= a.min_preg1,1,
		IF(a.bdate is not NULL AND d.DATE_SERV BETWEEN  a.min_preg1 AND a.bdate,1,
		IF(a.bdate is not NULL AND a.min_preg2 is not NULL AND d.DATE_SERV > a.min_preg2,1,0
  ))) rcount
FROM t_rdu_anc_labor a 
INNER JOIN t_person_db p ON a.HOSPCODE=p.HOSPCODE AND a.PID=p.PID
INNER JOIN chospital h ON a.hospcode=h.hoscode AND h.hostype IN(5,6,7,11,15)
LEFT JOIN tmp_diag_opd o ON a.HOSPCODE=o.HOSPCODE AND a.PID=o.PID 
	AND o.DATE_SERV BETWEEN @start_d AND @end_d  
LEFT JOIN tmp_drug_asu d ON o.hospcode=d.HOSPCODE AND o.PID=d.PID AND o.SEQ=d.SEQ 
		AND o.DATE_SERV=d.DATE_SERV AND CHK_PRG = 'Y' AND d.amount > 0 AND d.scount=1
ORDER BY rcount DESC;

INSERT IGNORE INTO s_rdu17
(
SELECT
@id,d.hospcode,concat(h.provcode,SUBSTR(CONCAT('00',h.distcode),-2),SUBSTR(CONCAT('00',h.subdistcode),-2),SUBSTR(CONCAT('00',h.mu),-2)) as areacode
,@send,DATE_FORMAT(now(),'%Y%m%d%H%i%s') as d_com,@b_year+543 as b_year
,COUNT(DISTINCT IF(tcount IN(1),CONCAT(hospcode,pid),NULL)) target
,COUNT(DISTINCT IF(rcount IN(1),CONCAT(hospcode,pid),NULL)) result
FROM t_ht_rdu d INNER JOIN chospital h ON d.hospcode=h.hoscode
GROUP BY hoscode
);
